import numpy as np

SYMBOLS = ".abcdefghijklmnopqrstuvwxyz"
_ROWS = {0: [0, 0.5, 0.3, 0.2], 1: [0.4, 0.1, 0.3, 0.2], 2: [0.3, 0.5, 0.0, 0.2], 3: [0.6, 0.2, 0.2, 0.0]}


def toy(context):
    # a planted model over ., a, b, c that looks only at the last symbol
    return np.array(_ROWS[context[-1]] + [0.0] * 23)


def only_a(context):
    # a model that never ends a name
    p = np.zeros(27)
    p[1] = 1.0
    return p


def tenths(context):
    # ten letters at 0.1 each: the running total ends at 0.9999999999999999
    p = np.zeros(27)
    p[17:27] = 0.1
    return p


class FixedU:
    # stands in for a generator: hands out the given u values in turn
    def __init__(self, us):
        self.us = list(us)

    def random(self):
        return self.us.pop(0)

import json
_W = {k: np.array(v) for k, v in json.load(open('makemore-mlp.json')).items() if k != 'about'}


def mlp_logits(context):
    e = _W["C"][np.array(context)].reshape(-1)
    return np.tanh(e @ _W["W1"] + _W["b1"]) @ _W["W2"] + _W["b2"]


def mlp(context):
    z = mlp_logits(context)
    p = np.exp(z - z.max())
    return p / p.sum()
